import type { Components } from '../../components';

/* istanbul ignore next */
export const getDynamicSlots = (
  { items = [] }: Partial<Components.KsTimeline>,
  wrapWithSlot: (slotName: string, children: unknown) => unknown,
) => {
  const dynamicSlots: unknown[] = [];

  items.forEach(({ title, description }, index) => {
    if (typeof title === 'function') {
      dynamicSlots.push(wrapWithSlot(`title-${index}`, title()));
    }

    if (typeof description === 'function') {
      dynamicSlots.push(wrapWithSlot(`description-${index}`, description()));
    }
  });

  return dynamicSlots;
};
