import { Component, Host, h, Prop, Fragment, Element, type ComponentInterface } from '@stencil/core';
import { noop } from 'lodash-es';
import type { TimelineItem, TimelineStatus } from './types';
import { getDynamicSlots } from './utils';

const prefix = 'timeline';
type TimelineStage = 'completed' | 'active' | 'upcoming';

/**
 * @part base - The base container part
 * @part title - The title element of the items in timeline.
 * @part description - The description element of the items in timeline.
 */
@Component({
  tag: 'ks-timeline',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsTimeline implements ComponentInterface {
  static __internal_renderDynamicSlots(
    props: Partial<KsTimeline>,
    wrapWithSlot: (slotName: string, children: unknown) => unknown,
  ) {
    return getDynamicSlots(props, wrapWithSlot);
  }

  @Element() el!: HTMLKsTimelineElement;

  /** The current active item index. */
  @Prop() activeIndex = 0;
  /** The timeline items, including each step's `title`, `description`, `disabled`, and `status` values. Use renderable `title` and `description` values to provide richer content for a step. */
  @Prop() items: TimelineItem[] = [];
  /** Disable all timeline items. */
  @Prop() disabled = false;
  /** Root status, only affecting the active item. */
  @Prop() status: TimelineStatus = 'default';

  private wrapWithSlot: (slotName: string, children: unknown) => unknown = noop;
  private setDynamicRenderDeps: (items: unknown[]) => void = noop;

  componentWillRender() {
    const dynamicSlots = getDynamicSlots(this, this.wrapWithSlot);
    this.setDynamicRenderDeps(dynamicSlots);
  }

  private getStage(index: number): TimelineStage {
    if (index < this.activeIndex) {
      return 'completed';
    }

    if (index === this.activeIndex) {
      return 'active';
    }

    return 'upcoming';
  }

  private getStatus(index: number, item: TimelineItem): TimelineStatus {
    if (item.status === 'error') {
      return 'error';
    }

    if (this.status === 'error' && index === this.activeIndex) {
      return 'error';
    }

    return 'default';
  }

  private renderTextContent(content: TimelineItem['title'] | TimelineItem['description'], slotName: string) {
    if (typeof content === 'string') {
      return content;
    }

    return <slot name={slotName} />;
  }

  private renderItem(item: TimelineItem, index: number) {
    const stage = this.getStage(index);
    const status = this.getStatus(index, item);
    const disabled = this.disabled || item.disabled || false;

    return (
      <div
        key={index}
        class={{
          [`${prefix}__item`]: true,
          [`${prefix}__item--${stage}`]: true,
          [`${prefix}__item--${status}`]: true,
          [`${prefix}__item--disabled`]: this.disabled || disabled,
        }}
        data-testid={`ks-timeline-index-w6MokP-${index}`}
      >
        <div class={`${prefix}__item-bar`} />
        <div class={`${prefix}__item-wrapper`}>
          <div part="title" class={`${prefix}__item-title`}>
            <span class={`${prefix}__item-indicator`} />
            {this.renderTextContent(item.title, `title-${index}`)}
          </div>
          <div part="description" class={`${prefix}__item-description`}>
            {this.renderTextContent(item.description, `description-${index}`)}
          </div>
        </div>
      </div>
    );
  }

  render() {
    return (
      <Host class="KsTimeline">
        <div class={prefix} part="base">
          {this.items.map((item, index) => (
            <Fragment>{this.renderItem(item, index)}</Fragment>
          ))}
        </div>
      </Host>
    );
  }
}
